+/** Theoretical sales use and all actual consumption, by item, for inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must be on or before to" });
+  const totals = new Map();
+  const add = (itemId, kind, qty) => {
+    if (!totals.has(itemId)) totals.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    totals.get(itemId)[kind] += Math.round(qty * 1000);
+  };
+  for (const sale of store.data.sales) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    for (const i of sale.ingredients) add(i.itemId, "theoretical", i.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) add(batch.itemId, "actual", m.qty);
+  }
+  return [...totals.values()].filter((r) => r.theoretical > 0 || r.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId)
+    .map((r) => ({ itemId: r.itemId, theoretical: r.theoretical / 1000, actual: r.actual / 1000, difference: (r.actual - r.theoretical) / 1000 }));
+}
