diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..2796830
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,33 @@
+import { AppError } from "../errors.js";
+import { isDate } from "../dates.js";
+import { importSales } from "../domain/sales.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Parses and validates a till CSV before atomically importing its sales. */
+export function importSalesCsv(store, text) {
+  const lines = text.split(/\r?\n/);
+  const header = parseCsv(lines.shift())[0] ?? [];
+  const keys = header.map((s) => s.trim());
+  if (keys.length !== HEADER.length || HEADER.some((k) => !keys.includes(k)))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty columns" });
+  const rows = [];
+  for (const [index, line] of lines.entries()) {
+    if (!line.trim()) continue;
+    const fail = (reason) => { throw new AppError("bad_request", { reason: `row ${index + 2}: ${reason}` }); };
+    if (!/^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/.test(line)) fail("invalid CSV");
+    const fields = parseCsv(line)[0];
+    if (fields.length !== keys.length) fail("wrong number of columns");
+    const r = Object.fromEntries(keys.map((k, i) => [k, fields[i].trim()]));
+    if (!r.ticket) fail("ticket is required");
+    if (!/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-]\d{2}:\d{2})$/.test(r.soldAt) ||
+        !Number.isFinite(Date.parse(r.soldAt)) || !isDate(r.soldAt.slice(0, 10))) fail("invalid soldAt");
+    const dishId = Number(r.dishId);
+    const qty = Number(r.qty);
+    if (!Number.isSafeInteger(dishId) || dishId < 1) fail("invalid dishId");
+    if (!Number.isFinite(qty) || qty <= 0 || Math.abs(qty * 1000 - Math.round(qty * 1000)) > 1e-8) fail("invalid qty");
+    rows.push({ ticket: r.ticket, soldAt: new Date(r.soldAt).toISOString(), dishId, qty, row: index + 2 });
+  }
+  return importSales(store, rows);
+}
